import{_ as t}from"./chunks/folders.9ioZn9MV.js";import{_ as e,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"フォルダを比較する","description":"2 つのフォルダを横断して新規・変更・削除されたファイルを確認し、ツリーを絞り込んで両側を同期します。","frontmatter":{"title":"フォルダを比較する","description":"2 つのフォルダを横断して新規・変更・削除されたファイルを確認し、ツリーを絞り込んで両側を同期します。"},"headers":[],"relativePath":"ja/guide/folders.md","filePath":"ja/guide/folders.md","lastUpdated":1794296122000}'),s={name:"ja/guide/folders.md"};function l(n,a,d,c,p,h){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="フォルダを比較する" tabindex="-1">フォルダを比較する <a class="header-anchor" href="#フォルダを比較する" aria-label="Permalink to &quot;フォルダを比較する&quot;">​</a></h1><p>2 つのフォルダが一致しているべきとき —— 作業用コピーとバックアップ、古い書き出し と新しい書き出し —— 1 ファイルずつ比べるのは骨が折れます。qDiff ならツリー全体を 一度に表示できます。</p><img src="'+t+'" alt="ファイルの状態が色分けされた 2 つのフォルダツリー" class="guide-shot"><h2 id="_2-つのフォルダを開く" tabindex="-1">2 つのフォルダを開く <a class="header-anchor" href="#_2-つのフォルダを開く" aria-label="Permalink to &quot;2 つのフォルダを開く&quot;">​</a></h2><p>2 つのフォルダをウィンドウにドラッグするか、<strong>ファイル → 開く</strong>から選びます。 フォルダの中のフォルダも比較されるので、全体像を把握できます。</p><h2 id="ツリーをひと目で読む" tabindex="-1">ツリーをひと目で読む <a class="header-anchor" href="#ツリーをひと目で読む" aria-label="Permalink to &quot;ツリーをひと目で読む&quot;">​</a></h2><ul><li><strong>緑</strong> —— どちらか一方にしか存在しないファイル。</li><li><strong>オレンジ</strong> —— 名前は同じだが内容が違うファイル。</li><li><strong>赤</strong> —— 反対側に存在しない（欠けている）ファイル。</li><li><strong>グレー</strong> —— 両側が一致しているファイル。</li></ul><h2 id="必要なものだけ表示する" tabindex="-1">必要なものだけ表示する <a class="header-anchor" href="#必要なものだけ表示する" aria-label="Permalink to &quot;必要なものだけ表示する&quot;">​</a></h2><p>状態フィルタで、すでに一致しているものをすべて隠せます。名前の一部を入力して 一覧を絞り込むこともできます。名前だけの簡易チェックを選ぶか、qDiff に内容まで 読み取らせるかを指定できます。見た目は合っているのに中身が古いかもしれない バックアップの確認に便利です。</p><p>大きなフォルダもすばやく開けるので、進捗バーを待たされることはありません。</p><h2 id="一覧からその場で整える" tabindex="-1">一覧からその場で整える <a class="header-anchor" href="#一覧からその場で整える" aria-label="Permalink to &quot;一覧からその場で整える&quot;">​</a></h2><p>ファイルを反対側へコピーしたり、残った不要なものを削除したり、グループ丸ごと 同期したり、すべて同じツリーから行えます。Finder に戻る必要はありません。</p><div class="tip custom-block"><p class="custom-block-title">安心して探索できます</p><p>操作を選ぶまで、ディスク上のデータは一切変更されません。比較の閲覧や絞り込みは 完全に安全です。</p></div><p>次は<a href="./projects.html">コミット前にプロジェクトを確認する</a>方法へ。</p>',14)])])}const m=e(s,[["render",l]]);export{u as __pageData,m as default};
